def C(account, topic, claim, source_url, source_label, date, evidence, strength, refs, quote=None, secondary_topics=None):
    return dict(account=account, topic=topic, secondary_topics=secondary_topics or [], claim=claim, quote=quote,
                source_url=source_url, source_label=source_label, date=date, evidence_note=evidence,
                evidence_strength=strength, evidence_refs=[E[r] for r in refs])

