def main():
    for i, c in enumerate(CLAIMS, 1):
        c["id"] = f"c{i:03d}"
        if c["quote"] and len(c["quote"].split()) > 25:
            raise SystemExit("quote too long: " + c["id"])
    data = {
      "meta": {"title": "Pro-Metabolic Research Commons",
               "updated": datetime.date.today().isoformat(),
               "strength_scale": ["Supported","Partly supported","Mixed","Weak / preliminary","Contradicted","Not assessed"],
               "note": "Summaries are paraphrased. Quotes are under 25 words and attributed. Not medical advice."},
      "topics": TOPICS, "accounts": ACCOUNTS, "claims": CLAIMS}
    out = os.path.join(ROOT, "data", "claims.json")
    with open(out, "w") as f: json.dump(data, f, indent=2, ensure_ascii=False)
    sync()
    print("wrote", len(CLAIMS), "claims")

def sync():
    """Mirror data/claims.json into data/claims.js so the site works from file:// (no server)."""
    src = os.path.join(ROOT, "data", "claims.json")
    with open(src) as f: data = json.load(f)
    with open(os.path.join(ROOT, "data", "claims.js"), "w") as f:
        f.write("/* AUTO-GENERATED from claims.json by tools/sync_data.py. Do not edit by hand. */\nwindow.RESEARCH_DATA = ")
        json.dump(data, f, ensure_ascii=False)
        f.write(";\n")

if __name__ == "__main__":
    main()
